inline EMCEndpointRefT *EMCEndpointRef::UnPack(const ::flatbuffers::resolver_function_t *_resolver) const {
  auto _o = std::make_unique<EMCEndpointRefT>();
  UnPackTo(_o.get(), _resolver);
  return _o.release();
}

inline void EMCEndpointRef::UnPackTo(EMCEndpointRefT *_o, const ::flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = ENDPOINT_ID(); if (_e) _o->ENDPOINT_ID = _e->str(); }
  { auto _e = ENDPOINT_KIND(); _o->ENDPOINT_KIND = _e; }
  { auto _e = RFE_ID(); if (_e) _o->RFE_ID = _e->str(); }
  { auto _e = RFB_ID(); if (_e) _o->RFB_ID = _e->str(); }
  { auto _e = NORAD_CAT_ID(); _o->NORAD_CAT_ID = _e; }
  { auto _e = OBJECT_ID(); if (_e) _o->OBJECT_ID = _e->str(); }
  { auto _e = BEM_ID(); if (_e) _o->BEM_ID = _e->str(); }
  { auto _e = PAP_ID(); if (_e) _o->PAP_ID = _e->str(); }
  { auto _e = CHANNEL_ID(); if (_e) _o->CHANNEL_ID = _e->str(); }
}

inline ::flatbuffers::Offset<EMCEndpointRef> CreateEMCEndpointRef(::flatbuffers::FlatBufferBuilder &_fbb, const EMCEndpointRefT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return EMCEndpointRef::Pack(_fbb, _o, _rehasher);
}

